import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
import * as ENV from "../config";

// Fetch all jobs
export const fetchJobs = createAsyncThunk("jobs/fetchJobs", async () => {
  const res = await axios.get(`${ENV.SERVER_URL}/jobs`);
  return res.data;
});

// Fetch jobs for one company
export const fetchCompanyJobs = createAsyncThunk(
  "jobs/fetchCompanyJobs",
  async (email) => {
    const res = await axios.get(`${ENV.SERVER_URL}/jobs/company/${email}`);
    return res.data;
  }
);

// Add new job
export const addJob = createAsyncThunk("jobs/addJob", async (jobData) => {
  const res = await axios.post(`${ENV.SERVER_URL}/jobs`, jobData);
  return res.data;
});

// Update job
export const updateJob = createAsyncThunk("jobs/updateJob", async (job) => {
  const res = await axios.put(`${ENV.SERVER_URL}/jobs/${job._id}`, job);
  return res.data;
});

// Delete job
export const deleteJob = createAsyncThunk("jobs/deleteJob", async (id) => {
  await axios.delete(`${ENV.SERVER_URL}/jobs/${id}`);
  return id;
});

const jobSlice = createSlice({
  name: "jobs",
  initialState: {
    jobs: [],
    companyJobs: [],
    isLoading: false,
  },
  reducers: {},

  extraReducers: (builder) => {
    builder
      .addCase(fetchJobs.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchJobs.fulfilled, (state, action) => {
        state.jobs = action.payload;
        state.isLoading = false;
      })

      .addCase(fetchCompanyJobs.fulfilled, (state, action) => {
        state.companyJobs = action.payload;
      })

      .addCase(addJob.fulfilled, (state, action) => {
        state.jobs.push(action.payload);
      })

      .addCase(updateJob.fulfilled, (state, action) => {
        const index = state.companyJobs.findIndex(
          (j) => j._id === action.payload._id
        );
        if (index !== -1) state.companyJobs[index] = action.payload;
      })

      .addCase(deleteJob.fulfilled, (state, action) => {
        state.companyJobs = state.companyJobs.filter(
          (job) => job._id !== action.payload
        );
      });
  },
});

export default jobSlice.reducer;
